import { useState } from 'react';
import '../styles/RequestList.css';

const statusMap = {
  pending: 'В ожидании',
  in_progress: 'В работе',
  completed: 'Выполнена',
  rejected: 'Отклонена',
};

const RequestList = ({ requests, userRole, onStatusChange }) => {
  const [filterType, setFilterType] = useState('');
  const [filterStatus, setFilterStatus] = useState('');

  const filtered = requests.filter(req => {
    return (!filterType || req.type === filterType) && (!filterStatus || req.status === filterStatus);
  });

  const canChangeStatus = userRole === 'employee' || userRole === 'admin';

  return (
    <div className="request-list-container">
      <h2>Список заявок</h2>
      <div className="filters">
        <select value={filterType} onChange={(e) => setFilterType(e.target.value)}>
          <option value="">Все типы</option>
          <option value="event">Мероприятия</option>
          <option value="repair">Ремонт</option>
          <option value="video">Видеосъёмка</option>
        </select>
        <select value={filterStatus} onChange={(e) => setFilterStatus(e.target.value)}>
          <option value="">Все статусы</option>
          <option value="pending">В ожидании</option>
          <option value="in_progress">В работе</option>
          <option value="completed">Выполнена</option>
          <option value="rejected">Отклонена</option>
        </select>
      </div>
      {filtered.length === 0 ? (
        <p className="no-requests">Нет заявок</p>
      ) : (
        <div className="request-cards">
          {filtered.map(req => (
            <div key={req.id} className="request-card">
              <div className="card-header">
                <span className="request-id">№{req.id}</span>
                <span className="request-type">{req.type === 'event' ? 'Мероприятие' : req.type === 'repair' ? 'Ремонт' : 'Видеосъёмка'}</span>
                <span className={`status-badge ${req.status}`}>{statusMap[req.status]}</span>
              </div>
              <div className="card-body">
                <p><strong>Создатель:</strong> {req.creatorFio}</p>
                {req.details && (
                  <div className="details">
                    {req.type === 'event' && (
                      <>
                        <p>Дата: {req.details.date} | {req.details.startTime} - {req.details.endTime}</p>
                        <p>Аудитория: {req.details.room}</p>
                      </>
                    )}
                    {req.type === 'repair' && (
                      <>
                        <p>Аудитория: {req.details.room}</p>
                        <p>Проблема: {req.details.description}</p>
                      </>
                    )}
                    {req.type === 'video' && (
                      <>
                        <p>Место: {req.details.location}</p>
                        <p>Время: {req.details.startTime} - {req.details.endTime}</p>
                      </>
                    )}
                  </div>
                )}
                <p className="dates">Создана: {new Date(req.createdAt).toLocaleString()}</p>
                {req.statusChangedAt && <p className="dates">Изменена: {new Date(req.statusChangedAt).toLocaleString()}</p>}
              </div>
              {canChangeStatus && req.status !== 'completed' && req.status !== 'rejected' && (
                <div className="card-actions">
                  {req.status === 'pending' && (
                    <button onClick={() => onStatusChange(req.id, 'in_progress')}>В работу</button>
                  )}
                  {req.status === 'in_progress' && (
                    <>
                      <button onClick={() => onStatusChange(req.id, 'completed')}>Выполнена</button>
                      <button onClick={() => onStatusChange(req.id, 'rejected')}>Отклонить</button>
                    </>
                  )}
                </div>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default RequestList;
